UPDATE PackageDefinition SET DisplayName=PackageName,StandardName=PackageName,PackageFamily=(SELECT PackageFamily FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),ComponentType='Other',Length=(SELECT Length FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),Width=(SELECT Width FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),Height=(SELECT Height FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),BodyLength=(SELECT Length FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),BodyWidth=(SELECT Width FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),LeadCount=(SELECT LeadCount FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),PadCount=(SELECT LeadCount FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),Pitch=(SELECT Pitch FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),LeadLength=(SELECT LeadLength FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),LeadWidth=(SELECT LeadWidth FROM DiscreteSeed s WHERE s.PackageName=PackageDefinition.PackageName),ThermalPadLength=CASE WHEN PackageName IN ('DPAK','D2PAK','D3PAK','SOT223') THEN BodyLength ELSE 0 END,ThermalPadWidth=CASE WHEN PackageName IN ('DPAK','D2PAK','D3PAK','SOT223') THEN BodyWidth ELSE 0 END,IPCName=PackageName,JEDECName=PackageName,YamahaName='',MirtecAoiClass=CASE WHEN PackageName LIKE 'SOT%' THEN 'SOT' WHEN PackageName LIKE 'SOD%' THEN 'SOD' ELSE 'POWER_SEMICONDUCTOR' END,Description='Physical discrete semiconductor package',Notes='Nominal package dimensions; consult manufacturer drawing for tolerance and thermal tab footprint.' WHERE PackageName IN(SELECT PackageName FROM DiscreteSeed);
INSERT OR IGNORE INTO PackageDefinition(PackageName,DisplayName,StandardName,PackageFamily,ComponentType,CategoryId,FamilyId,Length,Width,Height,BodyLength,BodyWidth,LeadCount,PadCount,Pitch,LeadLength,LeadWidth,IPCName,JEDECName,YamahaName,MirtecAoiClass,Description,Notes,IsActive,CreatedAt,UpdatedAt) SELECT s.PackageName,s.PackageName,s.PackageName,s.PackageFamily,'Other',c.Id,f.Id,s.Length,s.Width,s.Height,s.Length,s.Width,s.LeadCount,s.LeadCount,s.Pitch,s.LeadLength,s.LeadWidth,s.PackageName,s.PackageName,'',CASE WHEN s.PackageName LIKE 'SOT%' THEN 'SOT' WHEN s.PackageName LIKE 'SOD%' THEN 'SOD' ELSE 'POWER_SEMICONDUCTOR' END,'Physical discrete semiconductor package','Nominal package dimensions; consult manufacturer drawing for tolerance and thermal tab footprint.',1,datetime('now'),datetime('now') FROM DiscreteSeed s JOIN PackageCategory c ON c.Code='DISCRETE' JOIN PackageFamily f ON f.CategoryId=c.Id AND f.Code=s.PackageFamily;
CREATE TEMP TABLE IF NOT EXISTS DiscreteAlias(PackageName TEXT, Alias TEXT); DELETE FROM DiscreteAlias;
