INSERT INTO MasterLibrary_PackageAliases(PackageId,Alias,AliasType,Source) SELECT p.Id,a.Alias,'Standard','Discrete seed 020' FROM DiscreteAlias a JOIN PackageDefinition p ON p.PackageName=a.PackageName WHERE NOT EXISTS(SELECT 1 FROM MasterLibrary_PackageAliases x WHERE x.PackageId=p.Id AND lower(x.Alias)=lower(a.Alias));
DROP TABLE DiscreteAlias; DROP TABLE DiscreteSeed;
